'use strict';
// Standalone research preview. All results are generated by the new model.
// Only physical metadata is shared with the direct solver; no proof fallback.
function iterationResearchPreview(layout,A,{ms=60000,maxTicks=216000,...options}={}){
 const started=performance.now(),remaining=()=>Math.max(0,ms-(performance.now()-started));
 const spec=factoryCompileSymbolicSpec(layout),over={...spec,unlimitedWarehouse:true};
 // Geometry audit is independent of simulation semantics. Incomplete or
 // geometrically flagged editor layouts must not veto the rate solver.
 if(layout!==state)throw Error('preview requires current layout context');
 const actual=iterationBoundaryPressure(spec,A,{...options,maxTicks,ms:ms*(options.actualBudgetFraction??.7)});
 const unlimited=iterationSolveComponents(over,A,{...options,maxTicks,ms:remaining()});
 return iterationAssemblePreview(layout,spec,A,actual,unlimited,started);
}
// Pure join of independent actual/pressure and unlimited branches.
function iterationAssemblePreview(layout,spec,A,actual,unlimited,started=performance.now()){
 const {q,txt,add,sub,mul,div,Z,U}=A,minus=(a,b)=>a==null||b==null?null:txt(sub(q(a),q(b)));
 const v=actual.actualValues,u=unlimited.values??null,read=(o,k)=>o===null||o[k]==null?null:o[k];
 const items=new Set(iterationLayoutWarehouseItems(layout,spec)),topology=iterationTopologyMaterialSets(spec),nodes=new Map(spec.machines.map(m=>[m.id,m]));
 // Preserve solved independent components without exposing a partial sum as
 // the whole-factory value. Unknown queries are explicit nulls.
 const solvedOver=unlimited.components.filter(c=>c.values);
 const overUnknown=new Set(unlimited.components.filter(c=>!c.values).flatMap(c=>c.possibleItems));
 const completeValues=(raw,{machines,routes,frozen,warehouse,complete})=>{
  const x=Object.fromEntries(Object.entries(raw||{}).filter(([k])=>!/^(inflow|outflow|net|localIn|localOut|localNet|frozenIn|frozenOut):/.test(k)));
  if(!complete)for(const k of Object.keys(x))if(/^(crafts|consumed):/.test(k))x[k]=null;
  const assign=(k,known)=>{x[k]=known?(raw?.[k]??'0'):null};
  for(const k of items){
   const rates=warehouse(k);
   for(const [p,value] of Object.entries(rates))x[p+':'+k]=value;
   x['net:'+k]=minus(x['inflow:'+k],x['outflow:'+k]);x['localNet:'+k]=minus(x['localIn:'+k],x['localOut:'+k]);
  }
  for(const m of spec.machines){
   const known=machines.has(m.id);
   for(const side of ['in','out'])assign('machineTotal:'+m.id+'|'+side,known);
   if(m.recipe){assign('cycle:'+m.id,known);x['machineDuty:'+m.id]=known?txt(mul(q(x['cycle:'+m.id]),q(m.recipe.seconds))):null}
  }
  for(const r of spec.routes){
   const known=routes.has(r.id)||!topology.connected.has(r.id);
   assign('routeTotal:'+r.id,known);
   const a=nodes.get(r.from),b=nodes.get(r.to);
   for(const k of topology.routes.get(r.id)){
    assign('flow:'+r.id+'|'+k,known);
    if(a?.outPorts.some(p=>p.index===r.fromPort))assign('machineMaterial:'+a.id+'|out|'+k,machines.has(a.id));
    if(b?.inputPriority.includes(r.toPort))assign('machineMaterial:'+b.id+'|in|'+k,machines.has(b.id));
   }
  }
  for(const f of spec.frozen)assign('duty:'+f.id,frozen.has(f.id));
  return x;
 };
 const av=completeValues(actual.partialValues,{complete:v!==null,machines:new Set(actual.solvedMachines),routes:new Set(actual.solvedRoutes),frozen:new Set(actual.solvedFrozen),warehouse:k=>{
  const p=actual.rows[k],fallback='0';
  const i=p?p.inflow:fallback,o=p?p.outflow:fallback,li=p?p.localInflow:fallback,lo=p?p.localOutflow:fallback;
  return {inflow:i,outflow:o,localIn:li,localOut:lo,frozenIn:minus(i,li),frozenOut:minus(o,lo)};
 }});
 const uv=completeValues(unlimited.partialValues,{complete:u!==null,machines:new Set(solvedOver.flatMap(c=>c.machines)),routes:new Set(solvedOver.flatMap(c=>c.routes)),frozen:new Set(solvedOver.flatMap(c=>c.frozen)),warehouse:k=>Object.fromEntries(['inflow','outflow','localIn','localOut','frozenIn','frozenOut'].map(p=>[p,overUnknown.has(k)?null:unlimited.partialValues[p+':'+k]??'0']))});
 const rows=Object.fromEntries([...items].map(k=>{
  const p=actual.rows[k],i=av['inflow:'+k],o=av['outflow:'+k],li=av['localIn:'+k],lo=av['localOut:'+k];
  const d=p?p.demand:'0',ld=p?p.localDemand:'0';
  return [k,{inflow:i,outflow:o,net:minus(i,o),potential:minus(i,d),overdraft:uv['net:'+k],withdrawalDemand:d,localNet:minus(li,lo),localPotential:minus(li,ld),localDemand:ld}];
 }));
 const sum=field=>Object.values(rows).some(r=>r[field]==null)?null:txt(Object.values(rows).reduce((s,r)=>add(s,q(r[field])),Z));
 const total=Object.fromEntries(['inflow','outflow','net','potential','overdraft'].map(k=>[k,sum(k)]));
 const machineTimes={};
 for(const m of spec.machines)if(m.recipe||m.type==='仓出'){const r=read(av,m.recipe?'cycle:'+m.id:'machineTotal:'+m.id+'|out');machineTimes[m.id]=r==null?null:q(r).n===0n?'Infinity':txt(div(U,q(r)))}
 const unknownMetrics=Object.entries(rows).flatMap(([k,r])=>['inflow','outflow','net','potential','overdraft','localPotential'].filter(f=>r[f]==null).map(f=>f+':'+k));
 if(v===null)unknownMetrics.push('actual:unresolved');if(u===null)unknownMetrics.push('unlimited:unresolved');
 return {status:unknownMetrics.length?'partial':'experimental-complete',certified:false,completeHtmlQueries:!unknownMetrics.length,values:av??{},unlimitedValues:uv??{},rows,total,machineTimes,unknownMetrics,actual,unlimited,elapsedMs:Math.round(performance.now()-started)};
}
